  "*.js",
  "*.cjs",
  "*.mjs",
  "*.ts",
  "*.cts",
  "*.mts",
  "*.tsx",
], { encoding: "utf8" })
  .trim()
  .split("\n")
  .filter(Boolean);

let changedFiles = 0;
let changedExpressions = 0;

