  const source = readFileSync(path, "utf8");
  const scriptKind = path.endsWith("x") ? ts.ScriptKind.TSX : ts.ScriptKind.TS;
  const sourceFile = ts.createSourceFile(path, source, ts.ScriptTarget.Latest, true, scriptKind);
  const insertions: number[] = [];

  const visit = (node: ts.Node): void => {
    if (ts.isRegularExpressionLiteral(node)) {
      const literal = node.getText(sourceFile);
      const finalSlash = literal.lastIndexOf("/");
      const flags = finalSlash === -1 ? "" : literal.slice(finalSlash + 1);
      if (!flags.includes("u") && !flags.includes("v")) insertions.push(node.end);
    }
    ts.forEachChild(node, visit);
