import { readFileSync, writeFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
import ts from "typescript";

const paths = execFileSync("git", [
  "ls-files",
  "*.js",
  "*.cjs",
  "*.mjs",
  "*.ts",
  "*.cts",
  "*.mts",
  "*.tsx",
], { encoding: "utf8" })
  .trim()
  .split("\n")
  .filter(Boolean);

let changedFiles = 0;

for (const filePath of paths) {
  const source = readFileSync(filePath, "utf8");
  const scriptKind = filePath.endsWith("x") ? ts.ScriptKind.TSX : ts.ScriptKind.TS;
  const sourceFile = ts.createSourceFile(
    filePath,
    source,
    ts.ScriptTarget.Latest,
    true,
    scriptKind,
  );
  const pathImport = sourceFile.statements.find(
    (statement): statement is ts.ImportDeclaration =>
      ts.isImportDeclaration(statement) &&
      ts.isStringLiteral(statement.moduleSpecifier) &&
      statement.moduleSpecifier.text === "node:path" &&
      statement.importClause?.namedBindings !== undefined &&
      ts.isNamedImports(statement.importClause.namedBindings),
  );
  if (pathImport === undefined || pathImport.importClause === undefined) continue;
  const namedBindings = pathImport.importClause.namedBindings;
  if (!ts.isNamedImports(namedBindings)) continue;

  const names = namedBindings.elements.map((element) =>
    element.propertyName === undefined
      ? element.name.text
      : `${element.propertyName.text}: ${element.name.text}`,
  );
  const finalImport = sourceFile.statements.filter(ts.isImportDeclaration).at(-1);
  if (finalImport === undefined) continue;

  const bindingName = source.includes("import path from \"node:path\"") ? "path" : "nodePath";
  const insertion = `\nconst { ${names.join(", ")} } = ${bindingName};\n`;
  let next = `${source.slice(0, finalImport.end)}${insertion}${source.slice(finalImport.end)}`;
  next = `${next.slice(0, pathImport.getStart(sourceFile))}import ${bindingName} from "node:path";${next.slice(pathImport.end)}`;
  writeFileSync(filePath, next);
  changedFiles += 1;
}

console.log(`Converted node:path imports in ${changedFiles} files.`);

