import { execFileSync, spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";

const lint = JSON.parse(
  spawnSync(
    "bunx",
    [
      "oxlint",
      "--config",
      "oxlint.config.ts",
      "--type-aware",
      "--format",
      "json",
      ".",
    ],
    { encoding: "utf8", maxBuffer: 16 * 1024 * 1024 }
  ).stdout
) as {
  readonly diagnostics: ReadonlyArray<{
    readonly code: string;
    readonly message: string;
  }>;
};

const symbols = new Set<string>();
for (const diagnostic of lint.diagnostics) {
  if (diagnostic.code !== "anti-slop(no-shape-in-symbol-names)") continue;
  const match = /Rename symbol "(?<symbol>[^"]+)"/u.exec(diagnostic.message);
  if (match?.groups?.symbol !== undefined) symbols.add(match.groups.symbol);
}

const paths = execFileSync(
  "git",
  ["ls-files", "*.js", "*.cjs", "*.mjs", "*.ts", "*.cts", "*.mts", "*.tsx"],
  { encoding: "utf8" }
)
  .trim()
  .split("\n")
  .filter(Boolean);

let changedFiles = 0;
for (const path of paths) {
  const source = readFileSync(path, "utf8");
  let next = source;
  for (const symbol of symbols) {
    const replacement = symbol.replace(/Shape$/u, "Contract");
    next = next.replaceAll(new RegExp(`\\b${symbol}\\b`, "gu"), replacement);
  }
  if (next === source) continue;
  writeFileSync(path, next);
  changedFiles += 1;
}

console.log(
  `Renamed ${symbols.size} shape-named contracts across ${changedFiles} files.`
);

