import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";

const renames = new Map([
  ["makeChannelEveChannel", "createChannelEveChannel"],
  ["makeWorkspaceSummary", "loadWorkspaceSummary"],
  ["makePreviewStateBackupStoreLive", "buildPreviewStateBackupStoreLive"],
  ["makeStableInfrastructureDriftStack", "buildStableInfrastructureDriftStack"],
  ["makeUpstashPersistenceLayer", "buildUpstashPersistenceLayer"],
  ["makeCodexProxyConfig", "loadCodexProxyConfig"],
  ["makeCodexProxyAppLayer", "buildCodexProxyAppLayer"],
  ["makeCodexProxyWebHandler", "createCodexProxyWebHandler"],
  [
    "makeCodexProxyOpenAICompatibleProxyLocal",
    "buildCodexProxyOpenAICompatibleProxyLocal",
  ],
  [
    "makeCodexProxyOpenAICompatibleProxyMockLive",
    "buildCodexProxyOpenAICompatibleProxyMockLive",
  ],
]);

const paths = execFileSync(
  "git",
  ["ls-files", "*.js", "*.cjs", "*.mjs", "*.ts", "*.cts", "*.mts", "*.tsx"],
  { encoding: "utf8" }
)
  .trim()
  .split("\n")
  .filter(Boolean);

let changedFiles = 0;
for (const path of paths) {
  const source = readFileSync(path, "utf8");
  let next = source;
  for (const [current, replacement] of renames) {
    next = next.replaceAll(new RegExp(`\\b${current}\\b`, "gu"), replacement);
  }
  if (next === source) continue;
  writeFileSync(path, next);
  changedFiles += 1;
}

console.log(`Renamed runtime builders across ${changedFiles} files.`);

