        4
      );
      assert.strictEqual(
        requests.some((request) =>
          request.params.some(
            ([key, value]) => key === "offset" && value === "1"
          )
        ),
        true
      );
      const encoded = Schema.encodeSync(Schema.UnknownFromJsonString)(
        observations
      );
      for (const sentinel of [
        "test-project-secret-sentinel",
