/**
 * Runtime behavior tweaks for a Spectrum instance.
 */
interface SpectrumOptions {
  /**
   * When `true`, inbound `group` messages are never delivered whole. Instead,
   * each group item is yielded from `spectrum.messages` as its own
   * `[space, message]` tuple, in order. Items retain their individual
   * `id`, `sender`, `timestamp`, and `.react()` / `.reply()` methods.
   *
   * Does not affect outbound `group(...)` sends or `space.getMessage(id)`.
   *
   * @default false
   */
  flattenGroups?: boolean;
  /**
   * Minimum severity emitted by the SDK's structured logger (to both the
   * console and, when telemetry is on, OTLP). Applies process-wide and takes
   * precedence over the `LOG_LEVEL` environment variable when provided.
   *
   * @default "info"
   */
  logLevel?: LogLevel;
}
interface SpectrumFactoryOptions<Providers extends PlatformProviderConfig[]> {
  options?: SpectrumOptions;
  providers: [...Providers];
  telemetry?: boolean;
  webhookSecret?: string;
}
declare function Spectrum<const Providers extends PlatformProviderConfig[]>(options: {
  projectId: string;
  projectSecret: string;
} & SpectrumFactoryOptions<Providers>): Promise<SpectrumInstance<Providers> & {
  readonly config: ProjectData;
}>;
declare function Spectrum<const Providers extends PlatformProviderConfig[]>(options: {
  projectId?: never;
  projectSecret?: never;
} & SpectrumFactoryOptions<Providers>): Promise<SpectrumInstance<Providers>>;
//#endregion
